int expwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	DEBUG("Asked to write %u bytes at %llu.\n", (unsigned int)len, (unsigned long long)a);

	return(rawexpwrite_fully(a, buf, len, client, fua));
