/**
 * Set up the copy-on-write diff file for this connection.
 *
 * Create a new diff file (in the directory configured with cowdir, or
 * in the same directory as the exported file if cowdir is not set) and
 * a map tracking which blocks of the export are present in it. Blocks
 * written during this connection end up in the diff file only; the
 * master file is left alone, and the diff file is removed when the
 * connection is closed.
 *
 * @param client the CLIENT structure with .server, .exportsize and
 * .clientname set up correctly
 * @return true on success, false otherwise
 */
bool copyonwrite_prepare(CLIENT* client) {
	off_t i;
	_cleanup_g_free_ gchar* dir = NULL;
	_cleanup_g_free_ gchar* export_base = NULL;
	if (client->server->cowdir != NULL) {
		dir = g_strdup(client->server->cowdir);
	} else {
		dir = g_path_get_dirname(client->exportname);
	}
	export_base = g_path_get_basename(client->exportname);
	client->difffilename = g_strdup_printf("%s/%s-%s-%d.diff",dir,export_base,client->clientname,
		(int)getpid());
	msg(LOG_INFO, "About to create map and diff file %s", client->difffilename) ;
	client->difffile=open(client->difffilename,O_RDWR | O_CREAT | O_TRUNC,0600) ;
	if (client->difffile<0) {
		err("Could not create diff file (%m)");
		return false;
	}
	if ((client->difmap=calloc(client->exportsize/DIFFPAGESIZE,sizeof(uint32_t)))==NULL) {
		err("Could not allocate memory");
		return false;
	}
	for (i=0;i<client->exportsize/DIFFPAGESIZE;i++) client->difmap[i]=(uint32_t)-1;

	return true;
}

