			err(str);
		}
		if(setgid(gr->gr_gid)<0) {
			err("Could not set GID: %m");
		}
	}
	if (username) {
		pw = getpwnam(username);
		if(!pw) {
			str = g_strdup_printf("Invalid user name: %s", username);
			err(str);
		}
		if (setgroups(0, NULL)<0) {
